entries[291084] = { ["name"] = "Sanguinated Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nAkunda's Bite (45), Winter's Kiss (45), Anchor Weed (15), Expulsom (15), Hydrocore (15)\nCreate a Sanguinated Alchemist Stone.\nProfession:\nBattle for Azeroth Alchemy (100)\nTrainer:\nClever Kumali\nZone:\nZuldazar\nCost:\n10\n\nSanguinated Alchemist Stone\nBinds when picked up\nUnique-EquippedTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 24 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n50\nRequires Kul Tiran Alchemy\n(100)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[291085] = { ["name"] = "Imbued Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nAkunda's Bite (50), Winter's Kiss (50), Anchor Weed (20), Expulsom (20), Sanguicell (25)\nCreate an Imbued Alchemist Stone.\nProfession:\nBattle for Azeroth Alchemy (100)\nDiscovery:\nSanguinated Alchemist Stone\n\nImbued Alchemist Stone\nBinds when picked up\nUnique-EquippedTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 24 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n50\nRequires Kul Tiran Alchemy\n(100)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[291086] = { ["name"] = "Emblazoned Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nAkunda's Bite (60), Winter's Kiss (60), Anchor Weed (30), Expulsom (30), Sanguicell (250)\nCreate an Emblazoned Alchemist Stone.\nProfession:\nBattle for Azeroth Alchemy (100)\nDiscovery:\nImbued Alchemist Stone\n\nEmblazoned Alchemist Stone\nBinds when picked up\nUnique-EquippedTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 25 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n50\nRequires Kul Tiran Alchemy\n(100)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
